import { useSelector } from 'react-redux';
import { Navigate } from 'react-router-dom';
import axios from 'axios';

/** Count how many questions were attempted (not undefined) */
export function attempts_Number(result) {
    return result.filter((r) => r !== undefined).length;
}

/** Calculate total points earned */
export function earnPoints_Number(result, answers, point) {
    return result
        .map((element, i) => answers[i] === element)
        .filter((correct) => correct)
        .map(() => point)
        .reduce((prev, curr) => prev + curr, 0);
}

/** Pass if earned more than 50% of total points */
export function flagResult(totalPoints, earnPoints) {
    return (totalPoints * 50) / 100 < earnPoints;
}

/** Route guard — redirect to home if no username in store */
export function CheckUserExist({ children }) {
    const auth = useSelector((state) => state.result.userId);
    return auth ? children : <Navigate to="/" replace={true} />;
}

/** GET request helper */
export async function getServerData(url, callback) {
    const { data } = await axios.get(url);
    return callback ? callback(data) : data;
}

/** POST request helper */
export async function postServerData(url, result, callback) {
    const { data } = await axios.post(url, result);
    return callback ? callback(data) : data;
}
